// Función helper para obtener template por ID
export function getTemplate(templateId: string): ProjectTemplate | null {
  return PROJECT_TEMPLATES[templateId] || null;
}

// Función para listar todos los templates disponibles
export function getAvailableTemplates(): ProjectTemplate[] {
  return Object.values(PROJECT_TEMPLATES);
}